import Model from 'flarum/common/Model';
export default class Nominee extends Model {
  name = Model.attribute('name');
  description = Model.attribute('description');
  slug = Model.attribute('slug');
  imageUrl = Model.attribute('imageUrl');
  url = Model.attribute('url');
  metadata = Model.attribute('metadata');
  sortOrder = Model.attribute('sortOrder');
  createdAt = Model.attribute('createdAt', Model.transformDate);
  updatedAt = Model.attribute('updatedAt', Model.transformDate);
  category = Model.hasOne('category');
  voteCount = Model.attribute('voteCount');
  votePercentage = Model.attribute('votePercentage');
  realVoteCount = Model.attribute('realVoteCount');
  voteAdjustment = Model.attribute('voteAdjustment');
  rank = Model.attribute('rank');
  isWinner = Model.attribute('isWinner');
  isRunnerUp = Model.attribute('isRunnerUp');
  isThirdPlace = Model.attribute('isThirdPlace');
}
flarum.reg.add('huseyinfiliz-awards', 'common/models/Nominee', Nominee);