import Model from 'flarum/common/Model';
export default class Category extends Model {
  name = Model.attribute('name');
  slug = Model.attribute('slug');
  description = Model.attribute('description');
  sortOrder = Model.attribute('sortOrder');
  allowOther = Model.attribute('allowOther');
  createdAt = Model.attribute('createdAt', Model.transformDate);
  updatedAt = Model.attribute('updatedAt', Model.transformDate);
  award = Model.hasOne('award');
  nominees = Model.hasMany('nominees');
  votes = Model.hasMany('votes');
  otherSuggestions = Model.hasMany('otherSuggestions');
  nomineeCount = Model.attribute('nomineeCount');
  voteCount = Model.attribute('voteCount');
  userVoteIds = Model.attribute('userVoteIds');
  userPendingSuggestionsCount = Model.attribute('userPendingSuggestionsCount');
  hasUserVoted() {
    const ids = this.userVoteIds();
    return ids && ids.length > 0;
  }
  getUserVotedNomineeIds() {
    return this.userVoteIds() || [];
  }
}
flarum.reg.add('huseyinfiliz-awards', 'common/models/Category', Category);