import Model from 'flarum/common/Model';
export default class Award extends Model {
  name = Model.attribute('name');
  slug = Model.attribute('slug');
  year = Model.attribute('year');
  description = Model.attribute('description');
  startsAt = Model.attribute('startsAt', Model.transformDate);
  endsAt = Model.attribute('endsAt', Model.transformDate);
  status = Model.attribute('status');
  effectiveStatus = Model.attribute('effectiveStatus');
  showLiveVotes = Model.attribute('showLiveVotes');
  imageUrl = Model.attribute('imageUrl');
  createdAt = Model.attribute('createdAt', Model.transformDate);
  updatedAt = Model.attribute('updatedAt', Model.transformDate);
  categories = Model.hasMany('categories');
  categoryCount = Model.attribute('categoryCount');
  nomineeCount = Model.attribute('nomineeCount');
  voteCount = Model.attribute('voteCount');
  canViewResults = Model.attribute('canViewResults');
  isDraft() {
    return this.status() === 'draft';
  }
  isActive() {
    return this.status() === 'active';
  }
  hasEnded() {
    return this.status() === 'ended';
  }
  isPublished() {
    return this.status() === 'published';
  }
  isVotingOpen() {
    const now = new Date();
    const startsAt = this.startsAt();
    const endsAt = this.endsAt();
    return this.isActive() && (!startsAt || now >= startsAt) && (!endsAt || now <= endsAt);
  }
  canShowVotes() {
    return this.isPublished() || this.isActive() && this.showLiveVotes();
  }

  /**
   * Check if award has effectively ended (status or date-based)
   */
  hasEffectivelyEnded() {
    const status = this.effectiveStatus() || this.status();
    return status === 'ended' || status === 'published';
  }
}
flarum.reg.add('huseyinfiliz-awards', 'common/models/Award', Award);